umns: minmax(360px, 1.1fr) minmax(190px, 0.7fr) minmax(190px, 0.7fr) auto; align-items: stretch; border-top: 1px solid var(--line); background: rgb(12, 15, 13); }.metrics { display: grid; grid-template-columns: repeat(4, 1fr); }.metrics > div { display: flex; flex-direction: column; justify-content: center; padding: 18px; border-right: 1px solid var(--line); }.metrics span, .chart__label { font: 7px SFMono-Regular, Consolas, monospace; color: var(--muted); letter-spacing: 0.12em; }.metrics strong { margin-top: 10px; font: 400 clamp(18px, 2vw, 29px) SFMono-Regular, Consolas, monospace; letter-spacing: -0.06em; }.chart { min-width: 0px; padding: 17px 14px 10px; border-right: 1px solid var(--line); }.chart__label { display: flex; justify-content: space-between; }.chart__label small { color: var(--signal); font-size: 7px; }.chart svg { width: 100%; height: 91px; overflow: visible; margin-top: 8px; }.chart path { stroke: rgba(255, 255, 255, 0.07); stroke-width: 0.7; fill: none; }.chart polyline { stroke: var(--signal); stroke-width: 1.5; fill: none; vector-effect: non-scaling-stroke; filter: drop-shadow(rgba(170, 255, 30, 0.4) 0px 0px 3px); }.chart:last-of-type polyline { stroke: rgb(241, 244, 239); filter: none; }.run-controls { display: grid; grid-template-columns: 88px 74px 120px; gap: 8px; align-content: center; padding: 18px; }.button { height: 40px; border: 1px solid var(--line); background: transparent; font-size: 8px; font-weight: 750; letter-spacing: 0.12em; cursor: pointer; transition: 0.16s; }.button:hover { border-color: rgb(230, 238, 231); transform: translateY(-1px); }.button--accent { color: rgb(9, 11, 10); background: var(--signal); border-color: var(--signal); box-shadow: rgba(170, 255, 30, 0.08) 0px 0px 20px; }.button--accent:hover { box-shadow: rgba(170, 255, 30, 0.2) 0px 0px 24px; }.button--power { color: var(--signal); border-color: rgba(170, 255, 30, 0.3); }.button--power.power--off { color: rgb(255, 102, 93); border-color: rgba(255, 102, 93, 0.34);